    if (kw(&L->cur,"THEN")) { lex_next(L); skip_nl(L); }
    take = 0;
    if (is_meth) {
      ob = oop_find_obj(vm, name);
      if (ob)
        cd = &vm->classes[ob->class_idx];
      else
        cd = oop_find_class(vm, name);
      if (cd) {
        md = oop_find_method(cd, mname);
        if (md) take = 1;
      }
    } else {
      take = oop_find_obj(vm, name) ? 1 : 0;
    }
