      mode = 0;
    lex_next(L);
    if (kw(&L->cur, "PATH") || kw(&L->cur, "FILE") || kw(&L->cur, "TARGET") ||
        kw(&L->cur, "OF") || kw(&L->cur, "AT") || kw(&L->cur, "FOR"))
      lex_next(L);
    path[0] = 0; ref[0] = 0;
    if (resolve_str_arg(vm, L, path, sizeof path) != 0) {
      fail(vm, mode == 2 ? "IFOUTOFDATE needs target source â IFOUTOFDATE out in â¦ END"
           : mode == 1 ? "IFOLDER needs path ref â IFOLDER cache src â¦ END"
                       : "IFNEWER needs path ref â IFNEWER src cache â¦ END");
      return -1;
    }
